tasks.solution:
function fuelStatus(fuel) {
  // koşullara göre bir metin döndür
  if (fuel === 0) {
    return "boş";
  }
  if (fuel < 30) {
    return "az";
  }
  return "yeterli";
}

console.log(fuelStatus(0));
console.log(fuelStatus(15));
console.log(fuelStatus(80));

check.js:
assert(fuelStatus(0) === "boş", "fuelStatus(0) \"boş\" döndürmeli.");
assert(fuelStatus(15) === "az" && fuelStatus(29) === "az" && fuelStatus(1) === "az", "30'dan az yakıt için \"az\" döndürmeli.");
assert(fuelStatus(30) === "yeterli" && fuelStatus(100) === "yeterli", "30 ve üstü için \"yeterli\" döndürmeli.");

