assert(launchMessage("Şahin", 10) === "Şahin 10 saniye içinde kalkıyor!", "launchMessage(\"Şahin\", 10) 'Şahin 10 saniye içinde kalkıyor!' döndürmeli.");
assert(launchMessage("Atmaca", 7) === "Atmaca 7 saniye içinde kalkıyor!" && launchMessage("Nova") === "Nova 3 saniye içinde kalkıyor!", "Fonksiyon başka gemi adları ve sürelerle de çalışmalı.");

challenge.starter:
function maxOf(numbers) {
  // döngüyle en büyük sayıyı bul ve döndür
}

console.log(maxOf([4, 18, 7, 12]));

challenge.solution:
function maxOf(numbers) {
  // döngüyle en büyük sayıyı bul ve döndür
  let max = numbers[0];
  for (const n of numbers) {
    if (n > max) {
      max = n;
    }
  }
  return max;
}

console.log(maxOf([4, 18, 7, 12]));

check.js:
assert(!/Math\.max/.test(_code), "Math.max kullanmadan, döngüyle bul.");
assert(maxOf([4, 18, 7, 12]) === 18, "maxOf([4, 18, 7, 12]) 18 döndürmeli.");
assert(maxOf([3, 9, 2]) === 9 && maxOf([7]) === 7 && maxOf([1, 2, 3, 50]) === 50, "maxOf başka dizilerle de doğru çalışmalı.");
assert(maxOf([-5, -2, -9]) === -2, "maxOf([-5, -2, -9]) -2 döndürmeli; başlangıç değerine dikkat.");

