project_task.solution:
// attack fonksiyonunu yaz
function attack(enemyHealth, damage = 10) {
  const result = enemyHealth - damage;
  if (result < 0) {
    return 0;
  }
  return result;
}

let boss = 100;
// boss'a iki kez saldır
boss = attack(boss, 35);
boss = attack(boss);

console.log("Boss canı:", boss);

check.js:
assert(attack(50, 25) === 25 && attack(80, 30) === 50, "attack(50, 25) 25 döndürmeli.");
assert(attack(50) === 40, "damage verilmezse 10 olmalı: attack(50) 40 döndürmeli.");
assert(attack(5) === 0 && attack(20, 50) === 0 && attack(30, 30) === 0, "Can 0'ın altına düşmemeli: attack(5) 0 döndürmeli.");
assert(boss === 55, "İki saldırıdan sonra boss 55 olmalı.");
assert(!/boss\s*=\s*55/.test(_code) && /attack\s*\(\s*boss\s*\)/.test(_code), "Boss'a attack(boss, 35) ve attack(boss) ile saldır; sonucu elle yazma.");
assert(_lines.includes("Boss canı: 55"), "Çıktıda 'Boss canı: 55' görünmeli.");

