project_task.solution:
// makeTitle fonksiyonunu yaz
function makeTitle(text, symbol = "*") {
  return `${symbol} ${text.toLocaleUpperCase("tr")} ${symbol}`;
}

const menu = ["ana sayfa", "projeler", "iletişim"];
// her bölümün başlığını yazdır
for (const item of menu) {
  console.log(makeTitle(item));
}

// hakkımda başlığını # ile yazdır
console.log(makeTitle("hakkımda", "#"));

check.js:
assert(makeTitle("blog") === "* BLOG *", "makeTitle(\"blog\") '* BLOG *' döndürmeli.");
assert(makeTitle("iletişim") === "* İLETİŞİM *", "makeTitle(\"iletişim\") '* İLETİŞİM *' döndürmeli; Türkçe büyük harf için toLocaleUpperCase(\"tr\") kullan.");
assert(makeTitle("oyunlar", "~") === "~ OYUNLAR ~", "makeTitle(\"oyunlar\", \"~\") '~ OYUNLAR ~' döndürmeli.");
assert(["* ANA SAYFA *", "* PROJELER *", "* İLETİŞİM *", "# HAKKIMDA #"].every((t) => _lines.includes(t)), "Çıktıda menüdeki üç başlık ve '# HAKKIMDA #' görünmeli.");
assert((_code.match(/console\.log/g) || []).length <= 2, "Her başlık için ayrı console.log yazma; döngü kullan.");

