project_task.solution:
const tasks = [];
const done = [];

function addTask(title) {
  tasks.push(title);
  return tasks.length;
}

function completeTask(title) {
  const index = tasks.indexOf(title);
  if (index === -1) {
    return false;
  }
  tasks.splice(index, 1);
  done.push(title);
  return true;
}

addTask("Matematik ödevi");
addTask("Kitap okuma");
completeTask("Matematik ödevi");
console.log("Kalan:", tasks.join(", "), "| Biten:", done.join(", "));

check.js:
assert(same(tasks, ["Kitap okuma"]) && same(done, ["Matematik ödevi"]), "Kod çalıştıktan sonra tasks ['Kitap okuma'], done ['Matematik ödevi'] olmalı.");
assert(_lines.includes("Kalan: Kitap okuma | Biten: Matematik ödevi"), "Çıktıda 'Kalan: Kitap okuma | Biten: Matematik ödevi' görünmeli.");
const before = tasks.length;
assert(addTask("Deneme görevi") === before + 1 && tasks[tasks.length - 1] === "Deneme görevi", "addTask görevi sona eklemeli ve yeni görev sayısını döndürmeli.");
assert(completeTask("Deneme görevi") === true && !tasks.includes("Deneme görevi") && done.includes("Deneme görevi"), "completeTask görevi tasks'tan çıkarıp done'a eklemeli ve true döndürmeli.");
const snapshot = tasks.join("|");
assert(completeTask("Olmayan görev") === false && tasks.join("|") === snapshot && !done.includes("Olmayan görev"), "Listede olmayan bir görev için completeTask hiçbir şeyi değiştirmeden false döndürmeli.");

