project_task.solution:
function checkAnswer(answer, correct) {
  const a = answer.trim().toLocaleLowerCase("tr");
  const c = correct.trim().toLocaleLowerCase("tr");
  return a === c;
}

const correctAnswers = ["Dünya", "Jüpiter", "Mars"];
const userAnswers = [" dünya", "SATÜRN", "mars "];
let score = 0;

// Döngüyle cevapları kontrol et
for (let i = 0; i < userAnswers.length; i++) {
  if (checkAnswer(userAnswers[i], correctAnswers[i])) {
    score += 10;
  }
}

console.log("Puan:", score);

check.js:
assert(checkAnswer("Mars", "Mars") === true && checkAnswer("Mars", "Venüs") === false, "checkAnswer aynı cevaplar için true, farklı cevaplar için false döndürmeli.");
assert(checkAnswer("  mars ", "Mars") === true, "checkAnswer(\"  mars \", \"Mars\") true döndürmeli (boşluk ve büyük/küçük harf fark etmemeli).");
assert(checkAnswer("JÜPİTER", "Jüpiter") === true && checkAnswer("IŞIK", "ışık") === true, "Türkçe harfler için toLocaleLowerCase(\"tr\") kullan: checkAnswer(\"IŞIK\", \"ışık\") true olmalı.");
assert(score === 20, "score 20 olmalı (3 cevaptan 2'si doğru).");
assert(!/score\s*=\s*20/.test(_code), "Puanı elle yazma; döngüde checkAnswer ile hesapla.");
assert(_lines.includes("Puan: 20"), "Çıktıda 'Puan: 20' görünmeli.");
